import os
import re
import unicodedata
from flask import Flask, request, jsonify, send_file, abort
from functools import wraps
import hashlib
import hmac
import secrets

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', secrets.token_hex(32))
app.config['UPLOAD_DIR'] = os.environ.get('UPLOAD_DIR', '/var/app/uploads')
app.config['MAX_PATH_LEN'] = 255

# Allowed filename pattern - alphanumeric, hyphens, underscores, dots, forward slashes for subdirs
FILENAME_PATTERN = re.compile(r'^[a-zA-Z0-9][a-zA-Z0-9_.\-/]*$')

# Blocked path components
BLOCKED_SEQUENCES = ['..', '~', '\\', '\x00']

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token', '')
        if not token:
            abort(401)
        expected = hmac.new(app.config['SECRET_KEY'].encode(), b'valid-session', hashlib.sha256).hexdigest()
        if not hmac.compare_digest(token, expected):
            abort(403)
        return f(*args, **kwargs)
    return decorated

class PathValidator:
    """Validates and sanitizes file paths for the document storage system."""

    def __init__(self, base_dir):
        self.base_dir = os.path.realpath(base_dir)

    def _normalize_unicode(self, path):
        """Normalize unicode to NFC form to prevent homoglyph attacks."""
        return unicodedata.normalize('NFC', path)

    def _check_blocked_sequences(self, path):
        """Check for directory traversal sequences."""
        for seq in BLOCKED_SEQUENCES:
            if seq in path:
                return False
        return True

    def _validate_pattern(self, path):
        """Validate path matches allowed character pattern."""
        return FILENAME_PATTERN.match(path) is not None

    def _validate_path_length(self, path):
        """Ensure path isn't too long."""
        return len(path.encode('utf-8')) <= app.config['MAX_PATH_LEN']

    def resolve_safe_path(self, user_path):
        """Resolve a user-provided path safely within the base directory.

        Security measures:
        1. Unicode normalization (NFC)
        2. Blocked sequence detection
        3. Regex pattern validation
        4. Path length check
        5. Realpath containment check
        """
        if not user_path:
            return None

        # Step 1: Normalize unicode
        normalized = self._normalize_unicode(user_path)

        # Step 2: Check for blocked sequences
        if not self._check_blocked_sequences(normalized):
            return None

        # Step 3: Validate against allowed pattern
        if not self._validate_pattern(normalized):
            return None

        # Step 4: Length check
        if not self._validate_path_length(normalized):
            return None

        # Step 5: Resolve and verify containment
        # Use the original user_path for filesystem resolution to preserve
        # any OS-level path semantics that normalization might alter
        candidate = os.path.join(self.base_dir, user_path)
        real_candidate = os.path.realpath(candidate)

        if not real_candidate.startswith(self.base_dir + os.sep) and real_candidate != self.base_dir:
            return None

        return real_candidate

path_validator = PathValidator(app.config['UPLOAD_DIR'])

@app.route('/api/documents/<path:filepath>', methods=['GET'])
@require_auth
def get_document(filepath):
    """Retrieve a document from the storage system."""
    safe_path = path_validator.resolve_safe_path(filepath)
    if safe_path is None:
        abort(404)

    if not os.path.isfile(safe_path):
        abort(404)

    return send_file(safe_path)

@app.route('/api/documents/<path:filepath>', methods=['DELETE'])
@require_auth
def delete_document(filepath):
    """Delete a document from the storage system."""
    safe_path = path_validator.resolve_safe_path(filepath)
    if safe_path is None:
        abort(404)

    if not os.path.isfile(safe_path):
        abort(404)

    os.unlink(safe_path)
    return jsonify({'status': 'deleted', 'path': filepath})

@app.route('/api/documents', methods=['POST'])
@require_auth
def upload_document():
    """Upload a new document."""
    filepath = request.form.get('path', '')
    file = request.files.get('file')

    if not file:
        abort(400)

    safe_path = path_validator.resolve_safe_path(filepath)
    if safe_path is None:
        abort(400)

    os.makedirs(os.path.dirname(safe_path), exist_ok=True)
    file.save(safe_path)
    return jsonify({'status': 'uploaded', 'path': filepath}), 201

@app.route('/api/health', methods=['GET'])
def health_check():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    os.makedirs(app.config['UPLOAD_DIR'], exist_ok=True)
    app.run(host='127.0.0.1', port=8080, debug=False)
